/* ===== Reset & Base ===== */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  user-select: none;
  -webkit-user-select: none;
}

/* ===== Desktop ===== */
#desktop {
  position: fixed;
  inset: 0;
  background: #1a1a2e;
  z-index: 0;
}

/* ===== Desktop Icons ===== */
#desktop-icons {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  align-content: flex-start;
  gap: 8px;
  height: calc(100% - 48px);
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 90px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s;
  padding: 8px 4px;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.1);
}

.desktop-icon:active {
  background: rgba(255, 255, 255, 0.15);
}

.icon-symbol {
  font-size: 36px;
  line-height: 1;
  margin-bottom: 6px;
  pointer-events: none;
}

.icon-label {
  font-size: 11px;
  color: #fff;
  text-align: center;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
  pointer-events: none;
  line-height: 1.2;
}

/* ===== Window Container ===== */
#window-container {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 10;
}

/* ===== Window ===== */
.window {
  position: absolute;
  min-width: 320px;
  min-height: 200px;
  background: #1e1e2e;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45),
    0 0 0 1px rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  pointer-events: auto;
  transition: box-shadow 0.15s;
}

.window.focused {
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.55),
    0 0 0 1px rgba(255, 255, 255, 0.12);
}

/* Title bar */
.window-titlebar {
  display: flex;
  align-items: center;
  height: 36px;
  padding: 0 12px;
  background: #181825;
  cursor: default;
  flex-shrink: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.window.focused .window-titlebar {
  background: #1e1e2e;
}

.window-title {
  flex: 1;
  font-size: 13px;
  font-weight: 500;
  color: #cdd6f4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
}

/* Close button */
.window-close {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  color: #6c7086;
  font-size: 16px;
  cursor: pointer;
  border-radius: 6px;
  margin-left: 8px;
  transition: background 0.12s, color 0.12s;
  line-height: 1;
  padding: 0;
}

.window-close:hover {
  background: rgba(243, 139, 139, 0.15);
  color: #f38ba8;
}

/* Window body */
.window-body {
  flex: 1;
  overflow: auto;
  padding: 16px;
  color: #cdd6f4;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.window-body .placeholder {
  color: #6c7086;
  font-size: 13px;
}

/* Resize handle */
.window-resize {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
}

/* ===== Taskbar ===== */
#taskbar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: rgba(30, 30, 46, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  padding: 0 8px;
  z-index: 10000;
}

#taskbar-buttons {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 4px;
  overflow-x: auto;
  padding: 4px 0;
}

#taskbar-buttons::-webkit-scrollbar {
  display: none;
}

.taskbar-btn {
  height: 36px;
  padding: 0 14px;
  border: none;
  background: rgba(255, 255, 255, 0.06);
  color: #bac2de;
  font-size: 12px;
  font-weight: 500;
  border-radius: 6px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.12s, color 0.12s;
  flex-shrink: 0;
}

.taskbar-btn:hover {
  background: rgba(255, 255, 255, 0.12);
}

.taskbar-btn.active {
  background: rgba(137, 180, 250, 0.18);
  color: #89b4fa;
}

#taskbar-clock {
  padding: 0 12px;
  font-size: 13px;
  font-weight: 500;
  color: #bac2de;
  white-space: nowrap;
  flex-shrink: 0;
  min-width: 60px;
  text-align: right;
}

/**
 * Browser OS — Desktop Shell (Ticket 1)
 * Window manager, taskbar, desktop icons, clock.
 */

// ===== App Registry =====
const APPS = {
  notepad: {
    title: "Notepad",
    width: 600,
    height: 400,
    placeholder: "Notepad — coming soon",
  },
  calculator: {
    title: "Calculator",
    width: 300,
    height: 420,
    placeholder: "Calculator — coming soon",
  },
  minesweeper: {
    title: "Minesweeper",
    width: 480,
    height: 440,
    placeholder: "Minesweeper — coming soon",
  },
  spider: {
    title: "Spider Solitaire",
    width: 780,
    height: 540,
    placeholder: "Spider Solitaire — coming soon",
  },
};

// ===== State =====
let nextZIndex = 100; // start z-order above desktop
let windowIdCounter = 0;
const openWindows = new Map(); // appId → { id, element, titleEl, bodyEl, zIndex }

// ===== Utility =====
function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function generateId() {
  return ++windowIdCounter;
}

// ===== Clock =====
function updateClock() {
  const now = new Date();
  const hh = String(now.getHours()).padStart(2, "0");
  const mm = String(now.getMinutes()).padStart(2, "0");
  document.getElementById("taskbar-clock").textContent = `${hh}:${mm}`;
}
setInterval(updateClock, 1000);
updateClock();

// ===== Window Manager =====
function createWindow(appId) {
  const app = APPS[appId];
  if (!app) return null;

  // Single instance: focus existing window if already open
  if (openWindows.has(appId)) {
    focusWindow(openWindows.get(appId).id);
    return openWindows.get(appId).element;
  }

  const id = generateId();
  const container = document.getElementById("window-container");

  // Position: cascade
  const offset = openWindows.size * 24;
  const x = clamp(60 + offset, 0, window.innerWidth - app.width);
  const y = clamp(40 + offset, 0, window.innerHeight - 48 - app.height);

  const el = document.createElement("div");
  el.className = "window focused";
  el.dataset.appId = appId;
  el.dataset.windowId = id;
  el.style.width = app.width + "px";
  el.style.height = app.height + "px";
  el.style.left = x + "px";
  el.style.top = y + "px";
  el.style.zIndex = ++nextZIndex;

  // Title bar
  const titlebar = document.createElement("div");
  titlebar.className = "window-titlebar";

  const titleEl = document.createElement("span");
  titleEl.className = "window-title";
  titleEl.textContent = app.title;

  const closeBtn = document.createElement("button");
  closeBtn.className = "window-close";
  closeBtn.setAttribute("aria-label", "Close");
  closeBtn.innerHTML = "&#x2715;"; // ✕

  titlebar.appendChild(titleEl);
  titlebar.appendChild(closeBtn);
  el.appendChild(titlebar);

  // Body
  const body = document.createElement("div");
  body.className = "window-body";
  body.innerHTML = `<span class="placeholder">${app.placeholder}</span>`;
  el.appendChild(body);

  // Resize handle
  const resizeHandle = document.createElement("div");
  resizeHandle.className = "window-resize";
  el.appendChild(resizeHandle);

  container.appendChild(el);

  // Store reference
  const winData = { id, element: el, titleEl, bodyEl: body, appId };
  openWindows.set(appId, winData);

  // Setup interactions
  setupDrag(el, titlebar);
  setupResize(el, resizeHandle);
  setupFocus(el, id);

  // Close button
  closeBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    closeWindow(appId);
  });

  // Add taskbar button
  addTaskbarButton(appId, id);

  return el;
}

function closeWindow(appId) {
  const winData = openWindows.get(appId);
  if (!winData) return;

  winData.element.remove();
  openWindows.delete(appId);
  removeTaskbarButton(appId);
}

function focusWindow(id) {
  // Remove focused class from all windows
  document.querySelectorAll(".window.focused").forEach((w) => {
    w.classList.remove("focused");
  });

  // Find the window element by id
  for (const [, winData] of openWindows) {
    if (winData.id === id) {
      winData.element.classList.add("focused");
      winData.element.style.zIndex = ++nextZIndex;
      break;
    }
  }

  // Update taskbar active state
  updateTaskbarActive(id);
}

// ===== Dragging =====
function setupDrag(windowEl, titlebar) {
  let isDragging = false;
  let startX, startY, startLeft, startTop;

  titlebar.addEventListener("mousedown", (e) => {
    if (e.target.classList.contains("window-close")) return;

    isDragging = true;
    startX = e.clientX;
    startY = e.clientY;

    const rect = windowEl.getBoundingClientRect();
    startLeft = rect.left;
    startTop = rect.top;

    // Focus on drag start
    const winData = openWindows.get(windowEl.dataset.appId);
    if (winData) {
      focusWindow(winData.id);
    }

    e.preventDefault();
  });

  document.addEventListener("mousemove", (e) => {
    if (!isDragging) return;

    const dx = e.clientX - startX;
    const dy = e.clientY - startY;

    const app = APPS[windowEl.dataset.appId];
    const maxX = window.innerWidth - app.width;
    const maxY = window.innerHeight - 48 - app.height; // taskbar height

    const newLeft = clamp(startLeft + dx, 0, maxX);
    const newTop = clamp(startTop + dy, 0, maxY);

    windowEl.style.left = newLeft + "px";
    windowEl.style.top = newTop + "px";
  });

  document.addEventListener("mouseup", () => {
    isDragging = false;
  });
}

// ===== Resizing =====
function setupResize(windowEl, resizeHandle) {
  let isResizing = false;
  let startX, startY, startW, startH;

  resizeHandle.addEventListener("mousedown", (e) => {
    isResizing = true;
    startX = e.clientX;
    startY = e.clientY;
    startW = windowEl.offsetWidth;
    startH = windowEl.offsetHeight;

    const winData = openWindows.get(windowEl.dataset.appId);
    if (winData) {
      focusWindow(winData.id);
    }

    e.preventDefault();
    e.stopPropagation();
  });

  document.addEventListener("mousemove", (e) => {
    if (!isResizing) return;

    const dx = e.clientX - startX;
    const dy = e.clientY - startY;

    const newW = clamp(startW + dx, 320, window.innerWidth);
    const newH = clamp(startH + dy, 200, window.innerHeight - 48);

    windowEl.style.width = newW + "px";
    windowEl.style.height = newH + "px";
  });

  document.addEventListener("mouseup", () => {
    isResizing = false;
  });
}

// ===== Focus on click =====
function setupFocus(windowEl, id) {
  windowEl.addEventListener("mousedown", () => {
    focusWindow(id);
  });
}

// ===== Taskbar Buttons =====
function addTaskbarButton(appId, windowId) {
  const container = document.getElementById("taskbar-buttons");
  const app = APPS[appId];

  const btn = document.createElement("button");
  btn.className = "taskbar-btn active";
  btn.dataset.appId = appId;
  btn.dataset.windowId = windowId;
  btn.textContent = app.title;

  btn.addEventListener("click", () => {
    const winData = openWindows.get(appId);
    if (winData) {
      focusWindow(winData.id);
    }
  });

  container.appendChild(btn);
}

function removeTaskbarButton(appId) {
  const btn = document.querySelector(`.taskbar-btn[data-app-id="${appId}"]`);
  if (btn) btn.remove();
}

function updateTaskbarActive(activeWindowId) {
  document.querySelectorAll(".taskbar-btn").forEach((btn) => {
    const winData = openWindows.get(btn.dataset.appId);
    if (winData && winData.id === activeWindowId) {
      btn.classList.add("active");
    } else {
      btn.classList.remove("active");
    }
  });
}

// ===== Desktop Icon Double-Click =====
document.querySelectorAll(".desktop-icon").forEach((icon) => {
  let clickCount = 0;
  let clickTimer = null;

  icon.addEventListener("click", () => {
    clickCount++;
    if (clickCount === 1) {
      clickTimer = setTimeout(() => {
        clickCount = 0;
      }, 300);
    }
    if (clickCount >= 2) {
      clearTimeout(clickTimer);
      clickCount = 0;
      const appId = icon.dataset.app;
      createWindow(appId);
    }
  });
});

