#taskbar-clock {
  padding: 0 12px;
  font-size: 13px;
  font-weight: 500;
  color: #bac2de;
  white-space: nowrap;
  flex-shrink: 0;
  min-width: 60px;
  text-align: right;
}

/* ===== Calculator ===== */
.calc-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 0;
  background: #1e1e2e;
}

.calc-display {
  padding: 16px 20px;
  text-align: right;
  min-height: 80px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  background: #181825;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.calc-display-value {
  font-size: 36px;
  font-weight: 300;
  color: #cdd6f4;
  line-height: 1.2;
  word-break: break-all;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.calc-buttons {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  padding: 8px;
  flex: 1;
}

.calc-btn {
  border: none;
  border-radius: 8px;
  font-size: 18px;
  font-weight: 400;
  cursor: pointer;
  transition: background 0.12s, transform 0.08s;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  font-family: inherit;
  color: #cdd6f4;
  background: #313244;
  -webkit-tap-highlight-color: transparent;
}

.calc-btn:active {
  transform: scale(0.95);
}

.calc-btn:hover {
  background: #45475a;
}

/* Zero button spans two columns */
.calc-btn-zero {
  grid-column: span 2;
}

/* Function buttons (C, ±, %) */
.calc-btn-function {
  background: #45475a;
  color: #bac2de;
  font-size: 16px;
}

.calc-btn-function:hover {
  background: #585b70;
}

/* Operator buttons (÷, ×, −, +) */
.calc-btn-operator {
  background: #89b4fa;
  color: #1e1e2e;
  font-size: 22px;
  font-weight: 500;
}

.calc-btn-operator:hover {
  background: #74c7ec;
}

.calc-btn-operator.active-op {
  background: #b4befe;
}

/* Equals button */
.calc-btn-equals {
  background: #a6e3a1;
  color: #1e1e2e;
  font-size: 22px;
  font-weight: 500;
}

.calc-btn-equals:hover {
  background: #94e2d5;
}

/* Error state */
.calc-display-value.error {
  color: #f38ba8;
}

