function handleCalcButton(label) {
  if (calcError && label !== 'C') {
    // Clear error on any new input except C
    calcError = false;
    calcDisplayValue = '0';
    calcFirstOperand = null;
    calcOperator = null;
    calcWaitingForSecondOperand = false;
    calcLastOperand = null;
    calcLastOperator = null;
    calcJustEvaluated = false;
  }

  switch (label) {
    case 'C':
      calcClear();
      break;
    case '±':
      calcToggleSign();
      break;
    case '%':
      calcPercent();
      break;
    case '+':
    case '−':
    case '×':
    case '÷':
      calcHandleOperator(label);
      break;
    case '=':
      calcEvaluate();
      break;
    case '.':
      calcInputDecimal();
      break;
    default:
      if (label >= '0' && label <= '9') {
        calcInputDigit(label);
      }
      break;
  }

  updateCalcDisplay();
}

function calcClear() {
  calcDisplayValue = '0';
  calcFirstOperand = null;
  calcOperator = null;

