function calcPerformCalculation(op, a, b) {
  switch (op) {
    case '+':
      return formatCalcNumber(a + b);
    case '−':
      return formatCalcNumber(a - b);
    case '×':
      return formatCalcNumber(a * b);
    case '÷':
      if (b === 0) return 'Error';
      return formatCalcNumber(a / b);
    default:
      return formatCalcNumber(b);
  }
}

