window._initRunning = false;
window._initDone = true;
window._initEndTime = Date.now();

/* ===== Reset & Base ===== */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  user-select: none;
  -webkit-user-select: none;
}

/* ===== Desktop ===== */
#desktop {
  position: fixed;
  inset: 0;
  background: #1a1a2e;
  z-index: 0;
  transition: background 0.3s ease;
}

/* ===== Wallpaper Presets ===== */
#desktop.wp-midnight {
  background: #1a1a2e;
}

#desktop.wp-sunset {
  background: linear-gradient(135deg, #ff6b6b 0%, #ee5a24 40%, #f0932b 100%);
}

#desktop.wp-ocean {
  background: linear-gradient(180deg, #023e8a 0%, #0077b6 50%, #00b4d8 100%);
}

#desktop.wp-forest {
  background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 50%, #40916c 100%);
}

#desktop.wp-aurora {
  background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
}

#desktop.wp-lavender {
  background: radial-gradient(ellipse at 30% 40%, #e8dff5 0%, #b5a8d1 60%, #9887bd 100%);
}

#desktop.wp-grid {
  background-color: #1a1a2e;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px);
  background-size: 40px 40px;
}

#desktop.wp-diagonal {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  background-image: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 20px,
    rgba(255, 255, 255, 0.025) 20px,
    rgba(255, 255, 255, 0.025) 40px
  );
}

/* ===== Context Menu ===== */
.desktop-context-menu {
  position: fixed;
  background: rgba(30, 30, 46, 0.95);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45),
    0 0 0 1px rgba(255, 255, 255, 0.08);
  padding: 6px 0;
  min-width: 200px;
  z-index: 99999;
  color: #cdd6f4;
  font-size: 13px;
  display: none;
  user-select: none;
}

.desktop-context-menu.visible {
  display: block;
}

.desktop-context-menu-item {
  padding: 8px 16px;
  cursor: pointer;
  transition: background 0.12s;
  display: flex;
  align-items: center;
  gap: 8px;
}

.desktop-context-menu-item:hover {
  background: rgba(137, 180, 250, 0.15);
  color: #89b4fa;
}

.desktop-context-menu-separator {
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
  margin: 4px 12px;
}

/* ===== Wallpaper Picker ===== */
.wallpaper-picker {
  position: fixed;
  background: rgba(30, 30, 46, 0.95);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: 12px;
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.5),
    0 0 0 1px rgba(255, 255, 255, 0.08);
  padding: 16px;
  z-index: 100000;
  color: #cdd6f4;
  display: none;
  min-width: 360px;
}

.wallpaper-picker.visible {
  display: block;
}

.wallpaper-picker-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.wallpaper-picker-title {
  font-size: 14px;
  font-weight: 600;
  color: #cdd6f4;
}

.wallpaper-picker-close {
  width: 24px;
  height: 24px;
  border: none;
  background: transparent;
  color: #6c7086;
  font-size: 16px;
  cursor: pointer;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.12s, color 0.12s;
}

.wallpaper-picker-close:hover {
  background: rgba(243, 139, 139, 0.15);
  color: #f38ba8;
}

.wallpaper-picker-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.wallpaper-thumb {
