/* Error state */
.calc-display-value.error {
  color: #f38ba8;
}

/* ===== Notepad ===== */
.notepad-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 0;
  background: #1e1e2e;
  overflow: hidden;
}

.notepad-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  background: #181825;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.notepad-toolbar-btn {
  height: 30px;
  padding: 0 12px;
  border: none;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.12s, color 0.12s;
  font-family: inherit;
  color: #cdd6f4;
  background: #313244;
  white-space: nowrap;
}

.notepad-toolbar-btn:hover {
  background: #45475a;
}

.notepad-toolbar-btn:active {
  background: #585b70;
}

.notepad-toolbar-btn.save-btn:hover {
  background: rgba(166, 227, 161, 0.2);
  color: #a6e3a1;
}

.notepad-toolbar-btn.delete-btn:hover {
  background: rgba(243, 139, 139, 0.2);
  color: #f38ba8;
}

.notepad-main {
  display: flex;
  flex: 1;
  overflow: hidden;
}

.notepad-sidebar {
  width: 180px;
  min-width: 140px;
  background: #181825;
  border-right: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  flex-shrink: 0;
}

.notepad-sidebar-header {
  padding: 10px 12px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #6c7086;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.notepad-doc-list {
  flex: 1;
  overflow-y: auto;
  padding: 4px;
}

.notepad-doc-list::-webkit-scrollbar {
  width: 6px;
}

.notepad-doc-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
}

.notepad-doc-item {
  padding: 8px 12px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
  color: #bac2de;
  transition: background 0.12s, color 0.12s;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.notepad-doc-item:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #cdd6f4;
}

.notepad-doc-item.active {
  background: rgba(137, 180, 250, 0.15);
  color: #89b4fa;
}

.notepad-editor {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.notepad-textarea {
  flex: 1;
  width: 100%;
  border: none;
  outline: none;
  resize: none;
  padding: 16px;
  background: #1e1e2e;
  color: #cdd6f4;
  font-family: "SF Mono", "Fira Code", "Cascadia Code", Consolas, monospace;
  font-size: 14px;
  line-height: 1.6;
  tab-size: 4;
  -moz-tab-size: 4;
}

.notepad-textarea::placeholder {
  color: #45475a;
}

.notepad-textarea::-webkit-scrollbar {
  width: 8px;
}

.notepad-textarea::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 4px;
}

.notepad-empty-state {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #45475a;
  font-size: 13px;
}

