.notepad-empty-state {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #45475a;
  font-size: 13px;
}

/* Notepad Dialog */
.notepad-dialog-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999999;
}

.notepad-dialog {
  background: #1e1e2e;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.5);
  padding: 24px;
  min-width: 340px;
  max-width: 420px;
}

.notepad-dialog-title {
  font-size: 15px;
  font-weight: 600;
  color: #cdd6f4;
  margin-bottom: 16px;
}

.notepad-dialog-input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  background: #181825;
  color: #cdd6f4;
  font-size: 14px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s;
  margin-bottom: 16px;
}

.notepad-dialog-input:focus {
  border-color: #89b4fa;
}

.notepad-dialog-buttons {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.notepad-dialog-btn {
  height: 34px;
  padding: 0 16px;
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.12s;
}

.notepad-dialog-btn-cancel {
  background: #313244;
  color: #bac2de;
}

.notepad-dialog-btn-cancel:hover {
  background: #45475a;
}

.notepad-dialog-btn-ok {
  background: #89b4fa;
  color: #1e1e2e;
}

.notepad-dialog-btn-ok:hover {
  background: #74c7ec;
}

