/* ===== Minesweeper ===== */
.minesweeper-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 0;
  background: #1e1e2e;
  overflow: hidden;
  font-family: inherit;
}

.minesweeper-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: #181825;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
  gap: 8px;
}

.minesweeper-stat {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #f38ba8;
  min-width: 50px;
  justify-content: center;
  background: #11111b;
  padding: 4px 10px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.minesweeper-stat.timer-stat {
  color: #a6e3a1;
}

.minesweeper-stat-label {
  font-size: 10px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #6c7086;
}

.minesweeper-face-btn {
  width: 36px;
  height: 36px;
  border: none;
  border-radius: 8px;
  background: #313244;
  color: #cdd6f4;
  font-size: 20px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.12s, transform 0.08s;
  flex-shrink: 0;
}

.minesweeper-face-btn:hover {
  background: #45475a;
}

.minesweeper-face-btn:active {
  transform: scale(0.92);
}

.minesweeper-difficulty-bar {
  display: flex;
  gap: 4px;
  padding: 6px 12px;
  background: #181825;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.minesweeper-diff-btn {
  height: 28px;
  padding: 0 12px;
  border: none;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  color: #bac2de;
  background: #313244;
  transition: background 0.12s, color 0.12s;
}

.minesweeper-diff-btn:hover {
  background: #45475a;
}

.minesweeper-diff-btn.active {
  background: #89b4fa;
  color: #1e1e2e;
}

.minesweeper-board-wrapper {
  flex: 1;
  overflow: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
}

.minesweeper-board {
  display: grid;
  gap: 1px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 6px;
  padding: 1px;
}

.minesweeper-cell {
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 3px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition: background 0.06s;
  user-select: none;
  -webkit-user-select: none;
  padding: 0;
  line-height: 1;
}

/* Unrevealed cell */
.minesweeper-cell.hidden {
  background: #45475a;
  color: transparent;
}

.minesweeper-cell.hidden:hover {
  background: #585b70;
}

.minesweeper-cell.hidden:active {
  background: #6c7086;
}

/* Revealed cell */
.minesweeper-cell.revealed {
  background: #1e1e2e;
  cursor: default;
}

/* Flagged cell */
.minesweeper-cell.flagged {
  background: #45475a;
  color: #f9e2af;
}

/* Mine cells */
.minesweeper-cell.mine {
  background: #f38ba8;
  color: #1e1e2e;
}

.minesweeper-cell.mine-wrong {
  background: #eba0ac;
  color: #1e1e2e;
}

/* Number colors */
.minesweeper-cell.n1 { color: #89b4fa; }
.minesweeper-cell.n2 { color: #a6e3a1; }
.minesweeper-cell.n3 { color: #f38ba8; }
.minesweeper-cell.n4 { color: #cba6f7; }
.minesweeper-cell.n5 { color: #f9e2af; }
.minesweeper-cell.n6 { color: #94e2d5; }
.minesweeper-cell.n7 { color: #cdd6f4; }
.minesweeper-cell.n8 { color: #6c7086; }

/* Game over overlay */
.minesweeper-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  border-radius: 6px;
  z-index: 5;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s;
}

.minesweeper-overlay.visible {
  opacity: 1;
  pointer-events: auto;
}

.minesweeper-overlay-text {
  font-size: 22px;
  font-weight: 700;
  color: #fff;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
  padding: 8px 20px;
  border-radius: 8px;
  background: rgba(30, 30, 46, 0.85);
}

.minesweeper-overlay-text.win {
  color: #a6e3a1;
}

.minesweeper-overlay-text.lose {
  color: #f38ba8;
}

